import pandas as pd, numpy as np, sys, traceback
sys.path.insert(0, 'scripts')
from factor_validation_lib import load_closes, ASSETS
close, vol, open_, high, low = load_closes()
macro = {}
def f_skew_20(c, v, o, h, l, m):
    r = c.pct_change()
    return r.rolling(20).skew()
def f_range_pos_20(c, v, o, h, l, m):
    hi = h.rolling(20).max()
    lo = l.rolling(20).min()
    return (c - lo) / (hi - lo)
for name, fn in [('skew', f_skew_20), ('range', f_range_pos_20)]:
    print('---', name)
    for a in ASSETS:
        try:
            s = fn(close[a], vol[a], open_[a], high[a], low[a], macro)
            print(' ', a, 'valid', int(s.notna().sum()), 'len', len(s))
        except Exception as e:
            print(' ', a, 'EXC', repr(e)[:80])
